export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-23\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 23,\n    \"title\": \"喻老\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 11,\n    \"passageIds\": [\n      \"han-fei-zi_ch-23_p-1\",\n      \"han-fei-zi_ch-23_p-2\",\n      \"han-fei-zi_ch-23_p-3\",\n      \"han-fei-zi_ch-23_p-4\",\n      \"han-fei-zi_ch-23_p-5\",\n      \"han-fei-zi_ch-23_p-6\",\n      \"han-fei-zi_ch-23_p-7\",\n      \"han-fei-zi_ch-23_p-8\",\n      \"han-fei-zi_ch-23_p-9\",\n      \"han-fei-zi_ch-23_p-10\",\n      \"han-fei-zi_ch-23_p-11\",\n      \"han-fei-zi_ch-23_p-12\",\n      \"han-fei-zi_ch-23_p-13\",\n      \"han-fei-zi_ch-23_p-14\",\n      \"han-fei-zi_ch-23_p-15\",\n      \"han-fei-zi_ch-23_p-16\",\n      \"han-fei-zi_ch-23_p-17\",\n      \"han-fei-zi_ch-23_p-18\",\n      \"han-fei-zi_ch-23_p-19\",\n      \"han-fei-zi_ch-23_p-20\",\n      \"han-fei-zi_ch-23_p-21\",\n      \"han-fei-zi_ch-23_p-22\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-23_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 1,\n      \"canonicalText\": \"天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞。」天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而兵不歸，故曰：「戎馬生於郊。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-1_s-1\",\n        \"han-fei-zi_ch-23_p-1_s-2\",\n        \"han-fei-zi_ch-23_p-1_s-3\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"天下有道無急患則說道：靜，遽傳不用，因此韓絕不是子評論說道：卻走馬以糞。天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而且兵不歸，因此韓絕不是子評論說道：戎馬生於郊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「天」、「下」、「有」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「天下有道無急患則曰靜遽傳不用故曰卻走馬以糞天下無」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而兵不歸，故曰：「戎馬生於郊」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 2,\n      \"canonicalText\": \"翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪。」夫治國者以名號為罪，徐偃王是也。以城與地為罪，虞、虢是也。故曰：「罪莫大於可欲。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-2_s-1\",\n        \"han-fei-zi_ch-23_p-2_s-2\",\n        \"han-fei-zi_ch-23_p-2_s-3\",\n        \"han-fei-zi_ch-23_p-2_s-4\",\n        \"han-fei-zi_ch-23_p-2_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"翟人有獻豐狐、玄豹的皮於晉文公，文公受客皮而且歎說道：此以皮的美自為罪。夫治國的人或事以名號為罪，徐偃王是啊。以城與地為罪，虞、虢是啊。因此韓絕不是子評論說道：罪莫大於可欲。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「翟」、「人」、「有」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「翟人有獻豐狐玄豹之皮於晉文公文公受客皮而歎曰此以」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」夫治國者以名號為罪，徐偃王是也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 3,\n      \"canonicalText\": \"智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-3_s-1\",\n        \"han-fei-zi_ch-23_p-3_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"智伯兼範、中行而且攻趙不已，韓、魏反的，軍敗晉陽，身死高梁的東，遂卒被分，漆他的首以為溲器，因此韓絕不是子評論說道：禍莫大於不知足。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「智」、「伯」、「兼」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「智伯兼範中行而攻趙不已韓魏反之軍敗晉陽身死高梁之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 4,\n      \"canonicalText\": \"虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-4_s-1\",\n        \"han-fei-zi_ch-23_p-4_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"虞君主統治者欲屈產的乘，與垂棘的璧，不聽宮的奇，所以邦亡身死，因此韓絕不是子評論說道：咎莫憯於欲得。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「虞」、「君」、「欲」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「虞君欲屈產之乘與垂棘之璧不聽宮之奇故邦亡身死故曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 5,\n      \"canonicalText\": \"邦以存為常，霸王其可也。身以生為常，富貴其可也。不欲自害則邦不亡身不死，故曰：「知足之為足矣。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-5_s-1\",\n        \"han-fei-zi_ch-23_p-5_s-2\",\n        \"han-fei-zi_ch-23_p-5_s-3\",\n        \"han-fei-zi_ch-23_p-5_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"邦以存為常，霸王他的可啊。身以生為常，富貴他的可啊。不欲自害則邦不亡身不死，因此韓絕不是子評論說道：知足的為足矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「邦以存為常，霸王其可也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「邦」、「存」、「為」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「邦以存為常霸王其可也身以生為常富貴其可也不欲自害」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「身以生為常，富貴其可也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 6,\n      \"canonicalText\": \"楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處。楚邦之法，祿臣再世而收地，唯孫叔敖獨在。此不以其邦為收者，瘠也，故九世而祀不絕。故曰：「善建不拔，善抱不脫，子孫以其祭祀世世不輟」，孫叔敖之謂也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-6_s-1\",\n        \"han-fei-zi_ch-23_p-6_s-2\",\n        \"han-fei-zi_ch-23_p-6_s-3\",\n        \"han-fei-zi_ch-23_p-6_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"楚莊王既勝狩於河雍，歸而且賞賜孫叔敖，孫叔敖請漢間的地，沙石的處。楚邦的法規法令，祿臣屬再世而且收地，唯孫叔敖獨在。此不以他的邦為收的人或事，瘠啊，所以九世而且祀不絕。因此韓絕不是子評論說道：善建不拔，善抱不脫，子孫以他的祭祀世世不輟，孫叔敖的謂啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「楚」、「莊」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「楚莊王既勝狩於河雍歸而賞孫叔敖孫叔敖請漢間之地沙」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「楚邦之法，祿臣再世而收地，唯孫叔敖獨在」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 7,\n      \"canonicalText\": \"制在己曰重，不離位曰靜。重則能使輕，靜則能使躁。故曰：「重為輕根，靜為躁君。故曰君子終日行不離輜重也。」邦者，人君之輜重也。主父生傳其邦，此離其輜重者也。故雖有代、雲中之樂，超然已無趙矣。主父，萬乘之主，而以身輕於天下，無勢之謂輕，離位之謂躁，是以生幽而死。故曰：「輕則失臣，躁則失君」，主父之謂也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-7_s-1\",\n        \"han-fei-zi_ch-23_p-7_s-2\",\n        \"han-fei-zi_ch-23_p-7_s-3\",\n        \"han-fei-zi_ch-23_p-7_s-4\",\n        \"han-fei-zi_ch-23_p-7_s-5\",\n        \"han-fei-zi_ch-23_p-7_s-6\",\n        \"han-fei-zi_ch-23_p-7_s-7\",\n        \"han-fei-zi_ch-23_p-7_s-8\",\n        \"han-fei-zi_ch-23_p-7_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"制在己說道：重，不離位說道：靜。重則能使輕，靜則能使躁。因此韓絕不是子評論說道：重為輕根，靜為躁國君。因此韓絕不是子評論說道：國君子終日行不離輜重啊。邦的人或事，人國君的輜重啊。主父生傳他的邦，此離他的輜重的人或事啊。所以雖有代、雲中的樂，超然已無趙矣。主父，萬乘的主，而且以身輕於天下，無權位威勢的謂輕，離位的謂躁，是以生幽而且死。因此韓絕不是子評論說道：輕則失臣屬，躁則失國君，主父的謂啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「制在己曰重，不離位曰靜」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「制」、「在」、「己」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「制在己曰重不離位曰靜重則能使輕靜則能使躁故曰重為」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「重則能使輕，靜則能使躁」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 8,\n      \"canonicalText\": \"勢重者，人君之淵也。君人者勢重於人臣之閒，失則不可復得也。簡公失之於田成，晉公失之於六卿，而邦亡身死。故曰：「魚不可脫於深淵。」賞罰者，邦之利器也，在君則制臣，在臣則勝君。君見賞，臣則損之以為德；君見罰，臣則益之以為威。人君見賞而人臣用其勢，人君見罰而人臣乘其威。故曰：「邦之利器不可以示人。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-8_s-1\",\n        \"han-fei-zi_ch-23_p-8_s-2\",\n        \"han-fei-zi_ch-23_p-8_s-3\",\n        \"han-fei-zi_ch-23_p-8_s-4\",\n        \"han-fei-zi_ch-23_p-8_s-5\",\n        \"han-fei-zi_ch-23_p-8_s-6\",\n        \"han-fei-zi_ch-23_p-8_s-7\",\n        \"han-fei-zi_ch-23_p-8_s-8\",\n        \"han-fei-zi_ch-23_p-8_s-9\",\n        \"han-fei-zi_ch-23_p-8_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"權位威勢重的人或事，人國君的淵啊。國君人的人或事權位威勢重於人臣屬的閒，失則不可復得啊。簡公失的於田成，晉公失的於六卿，而且邦亡身死。因此韓絕不是子評論說道：魚不可脫於深淵。賞賜與刑罰的人或事，邦的利器啊，在國君則制臣屬，在臣屬則勝國君。國君見賞賜，臣屬則損的以為德；國君見刑罰，臣屬則益的以為威。人國君見賞賜而且人臣屬用他的權位威勢，人國君見刑罰而且人臣屬乘他的威。因此韓絕不是子評論說道：邦的利器不可以示人。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「勢重者，人君之淵也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「勢」、「重」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「勢重者人君之淵也君人者勢重於人臣之閒失則不可復得」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「君人者勢重於人臣之閒，失則不可復得也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 9,\n      \"canonicalText\": \"越王入宦於吳，而觀之伐齊以弊吳。吳兵既勝齊人於艾陵，張之於江、濟，強之於黃池，故可制於五湖。故曰：「將欲翕之，必固張之；將欲弱之，必固強之。」晉獻公將欲襲虞，遺之以璧馬；知伯將襲仇由，遺之以廣車。故曰：「將欲取之，必固與之。」起事於無形，而要大功於天下，是謂微明。處小弱而重自卑謂損弱勝強也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-9_s-1\",\n        \"han-fei-zi_ch-23_p-9_s-2\",\n        \"han-fei-zi_ch-23_p-9_s-3\",\n        \"han-fei-zi_ch-23_p-9_s-4\",\n        \"han-fei-zi_ch-23_p-9_s-5\",\n        \"han-fei-zi_ch-23_p-9_s-6\",\n        \"han-fei-zi_ch-23_p-9_s-7\",\n        \"han-fei-zi_ch-23_p-9_s-8\",\n        \"han-fei-zi_ch-23_p-9_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"越王入宦於吳，而且觀的伐齊以弊吳。吳兵既勝齊人於艾陵，張的於江、濟，強的於黃池，所以可制於五湖。因此韓絕不是子評論說道：將欲翕的，必固張的；將欲弱的，必固強的。晉獻公將欲襲虞，遺的以璧馬；知伯將襲仇由，遺的以廣車。因此韓絕不是子評論說道：將欲取的，必固與的。起事於無形，而且要大功於天下，是謂微明。處小弱而且重自卑謂損弱勝強啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「越王入宦於吳，而觀之伐齊以弊吳」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「越」、「王」、「入」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「越王入宦於吳而觀之伐齊以弊吳吳兵既勝齊人於艾陵張」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「吳兵既勝齊人於艾陵，張之於江、濟，強之於黃池，故可制於五湖」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 10,\n      \"canonicalText\": \"有形之類，大必起於小；行久之物，族必起於少。故曰：「天下之難事必作於易，天下之大事必作於細。」是以欲制物者於其細也，故曰：「圖難於其易也，為大於其細也。」千丈之隄以螻蟻之穴潰，百尺之室以突隙之煙焚。故曰：白圭之行隄也塞其穴，丈人之慎火也塗其隙。是以白圭無水難，丈人無火患。此皆慎易以避難，敬細以遠大者也。扁鵲見蔡桓公，立有間，扁鵲曰：「君有疾在腠理，不治將恐深。」桓侯曰：「寡人無。」扁鵲出，桓侯曰：「醫之好治不病以為功。」居十日，扁鵲復見曰：「君之病在肌膚，不治將益深。」桓侯不應。扁鵲出，桓侯又不悅。居十日，扁鵲復見曰：「君之病在腸胃，不治將益深。」桓侯又不應。扁鵲出，桓侯又不悅。居十日，扁鵲望桓侯而還走。桓侯故使人問之，扁鵲曰：「疾在腠理，湯熨之所及也；在肌膚，鍼石之所及也；在腸胃，火齊之所及也；在骨髓，司命之所屬，無奈何也。今在骨髓，臣是以無請也。」居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。故良醫之治病也，攻之於腠理，此皆爭之於小者也。夫事之禍福亦有腠理之地，故曰：聖人蚤從事焉。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-10_s-1\",\n        \"han-fei-zi_ch-23_p-10_s-2\",\n        \"han-fei-zi_ch-23_p-10_s-3\",\n        \"han-fei-zi_ch-23_p-10_s-4\",\n        \"han-fei-zi_ch-23_p-10_s-5\",\n        \"han-fei-zi_ch-23_p-10_s-6\",\n        \"han-fei-zi_ch-23_p-10_s-7\",\n        \"han-fei-zi_ch-23_p-10_s-8\",\n        \"han-fei-zi_ch-23_p-10_s-9\",\n        \"han-fei-zi_ch-23_p-10_s-10\",\n        \"han-fei-zi_ch-23_p-10_s-11\",\n        \"han-fei-zi_ch-23_p-10_s-12\",\n        \"han-fei-zi_ch-23_p-10_s-13\",\n        \"han-fei-zi_ch-23_p-10_s-14\",\n        \"han-fei-zi_ch-23_p-10_s-15\",\n        \"han-fei-zi_ch-23_p-10_s-16\",\n        \"han-fei-zi_ch-23_p-10_s-17\",\n        \"han-fei-zi_ch-23_p-10_s-18\",\n        \"han-fei-zi_ch-23_p-10_s-19\",\n        \"han-fei-zi_ch-23_p-10_s-20\",\n        \"han-fei-zi_ch-23_p-10_s-21\",\n        \"han-fei-zi_ch-23_p-10_s-22\",\n        \"han-fei-zi_ch-23_p-10_s-23\",\n        \"han-fei-zi_ch-23_p-10_s-24\",\n        \"han-fei-zi_ch-23_p-10_s-25\",\n        \"han-fei-zi_ch-23_p-10_s-26\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"有形的類，大必起於小；行久的物，族必起於少。因此韓絕不是子評論說道：天下的難事必作於易，天下的大事必作於細。是以欲制物的人或事於他的細啊，因此韓絕不是子評論說道：圖難於他的易啊，為大於他的細啊。千丈的隄以螻蟻的穴潰，百尺的室以突隙的煙焚。因此韓絕不是子評論說道：白圭的行隄啊塞他的穴，丈人的慎火啊塗他的隙。是以白圭無水難，丈人無火患。此皆慎易以避難，敬細以遠大的人或事啊。扁鵲見蔡桓公，立有間，扁鵲說道：國君有疾在腠理，不治將恐深。桓侯說道：寡人無。扁鵲出，桓侯說道：醫的好治不病以為功。居十日，扁鵲復見說道：國君的病在肌膚，不治將益深。桓侯不應。扁鵲出，桓侯又不悅。居十日，扁鵲復見說道：國君的病在腸胃，不治將益深。桓侯又不應。居十日，扁鵲望桓侯而且還走。桓侯所以使人問的，扁鵲說道：疾在腠理，湯熨的所及啊；在肌膚，鍼石的所及啊；在腸胃，火齊的所及啊；在骨髓，司命的所屬，無奈何啊。今在骨髓，臣屬是以無請啊。居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。所以良醫的治病啊，攻的於腠理，此皆爭的於小的人或事啊。夫事的禍福亦有腠理的地，因此韓絕不是子評論說道：聖人蚤從事焉。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「有形之類，大必起於小」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「有」、「形」、「類」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「有形之類大必起於小行久之物族必起於少故曰天下之難」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「行久之物，族必起於少」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 11,\n      \"canonicalText\": \"昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德。」鄭君不聽。叔瞻又諫曰：「不厚待之，不若殺之，無令有後患。」鄭君又不聽。及公子返晉邦，舉兵伐鄭，大破之，取八城焉。晉獻公以垂棘之璧假道於虞而伐虢，大夫宮之奇諫曰：「不可。脣亡而齒寒，虞、虢相救，非相德也。今日晉滅虢，明日虞必隨之亡。」虞君不聽，受其璧而假之道。晉已取虢，還，反滅虞。此二臣者皆爭於腠理者也，而二君不用也。然則叔瞻、宮之奇亦虞、鄭之扁鵲也，而二君不聽，故鄭以破，虞以亡。故曰：「其安易持也，其未兆易謀也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-11_s-1\",\n        \"han-fei-zi_ch-23_p-11_s-2\",\n        \"han-fei-zi_ch-23_p-11_s-3\",\n        \"han-fei-zi_ch-23_p-11_s-4\",\n        \"han-fei-zi_ch-23_p-11_s-5\",\n        \"han-fei-zi_ch-23_p-11_s-6\",\n        \"han-fei-zi_ch-23_p-11_s-7\",\n        \"han-fei-zi_ch-23_p-11_s-8\",\n        \"han-fei-zi_ch-23_p-11_s-9\",\n        \"han-fei-zi_ch-23_p-11_s-10\",\n        \"han-fei-zi_ch-23_p-11_s-11\",\n        \"han-fei-zi_ch-23_p-11_s-12\",\n        \"han-fei-zi_ch-23_p-11_s-13\",\n        \"han-fei-zi_ch-23_p-11_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"昔晉公子重耳出亡過鄭，鄭國君不禮，叔瞻諫說道：此賢公子啊，國君厚待的，可以積德。鄭國君不聽。叔瞻又諫說道：不厚待的，不若殺的，無令有後患。鄭國君又不聽。及公子返晉邦，舉兵伐鄭，大破的，取八城焉。晉獻公以垂棘的璧假道於虞而且伐虢，大夫宮的奇諫說道：不可。脣亡而且齒寒，虞、虢相救，絕不是相德啊。今日晉滅虢，明日虞必隨的亡。虞國君不聽，受他的璧而且假的道。晉已取虢，還，反滅虞。此二臣屬的人或事皆爭於腠理的人或事啊，而且二國君不用啊。然則叔瞻、宮的奇亦虞、鄭的扁鵲啊，而且二國君不聽，所以鄭以破，虞以亡。因此韓絕不是子評論說道：他的安易持啊，他的未兆易謀啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「昔」、「晉」、「公」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「昔晉公子重耳出亡過鄭鄭君不禮叔瞻諫曰此賢公子也君」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」鄭君不聽」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 12,\n      \"canonicalText\": \"昔者紂為象箸而箕子怖。以為象箸必不加於土鉶，必將犀玉之杯。象箸玉杯必不羹菽藿，則必旄象豹胎。旄象豹胎必不衣短褐而食於茅屋之下，則錦衣九重，廣室高臺。吾畏其卒，故怖其始。居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。故箕子見象箸以知天下之禍，故曰：「見小曰明。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-12_s-1\",\n        \"han-fei-zi_ch-23_p-12_s-2\",\n        \"han-fei-zi_ch-23_p-12_s-3\",\n        \"han-fei-zi_ch-23_p-12_s-4\",\n        \"han-fei-zi_ch-23_p-12_s-5\",\n        \"han-fei-zi_ch-23_p-12_s-6\",\n        \"han-fei-zi_ch-23_p-12_s-7\",\n        \"han-fei-zi_ch-23_p-12_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"昔的人或事紂為象箸而且箕子怖。以為象箸必不加於土鉶，必將犀玉的杯。象箸玉杯必不羹菽藿，則必旄象豹胎。旄象豹胎必不衣短褐而且食於茅屋的下，則錦衣九重，廣室高臺。吾畏他的卒，所以怖他的始。居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。所以箕子見象箸以知天下的禍，因此韓絕不是子評論說道：見小說道：明。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「昔者紂為象箸而箕子怖」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「昔」、「紂」、「為」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「昔者紂為象箸而箕子怖以為象箸必不加於土鉶必將犀玉」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「以為象箸必不加於土鉶，必將犀玉之杯」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 13,\n      \"canonicalText\": \"句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇。文王見詈於王門，顏色不變，而武王擒紂於牧野。故曰：「守柔曰強。」越王之霸也不病宦，武王之王也不病詈。故曰：「聖人之不病也，以其不病，是以無病也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-13_s-1\",\n        \"han-fei-zi_ch-23_p-13_s-2\",\n        \"han-fei-zi_ch-23_p-13_s-3\",\n        \"han-fei-zi_ch-23_p-13_s-4\",\n        \"han-fei-zi_ch-23_p-13_s-5\",\n        \"han-fei-zi_ch-23_p-13_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"句踐入宦於吳，身執干戈為吳王洗馬，所以能殺夫差於姑蘇。文王見詈於王門，顏色不變，而且武王擒紂於牧野。因此韓絕不是子評論說道：守柔說道：強。越王的霸啊不病宦，武王的王啊不病詈。因此韓絕不是子評論說道：聖人的不病啊，以他的不病，是以無病啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「句」、「踐」、「入」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「句踐入宦於吳身執干戈為吳王洗馬故能殺夫差於姑蘇文」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「文王見詈於王門，顏色不變，而武王擒紂於牧野」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 14,\n      \"canonicalText\": \"宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用。」子罕曰：「爾以玉為寶，我以不受子玉為寶。」是鄙人慾玉，而子罕不欲玉。故曰：「欲不欲，而不貴難得之貨。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-14_s-1\",\n        \"han-fei-zi_ch-23_p-14_s-2\",\n        \"han-fei-zi_ch-23_p-14_s-3\",\n        \"han-fei-zi_ch-23_p-14_s-4\",\n        \"han-fei-zi_ch-23_p-14_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"宋的鄙人得璞玉而且獻的子罕，子罕不受，鄙人說道：此寶啊，宜為君主統治者子器，不宜為細人用。子罕說道：爾以玉為寶，我以不受子玉為寶。是鄙人慾玉，而且子罕不欲玉。因此韓絕不是子評論說道：欲不欲，而且不貴難得的貨。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「宋」、「鄙」、「人」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「宋之鄙人得璞玉而獻之子罕子罕不受鄙人曰此寶也宜為」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」子罕曰：「爾以玉為寶，我以不受子玉為寶」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 15,\n      \"canonicalText\": \"王壽負書而行，見徐馮於周塗，馮曰：「事者，為也。為生於時，知者無常事。書者，言也。言生於知，知者不藏書。今子何獨負之而行？」於是王壽因焚其書而舞之。故知者不以言談教，而慧者不以藏書篋。此世之所過也，而王壽復之，是學不學也。故曰：「學不學，復歸眾人之所過也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-15_s-1\",\n        \"han-fei-zi_ch-23_p-15_s-2\",\n        \"han-fei-zi_ch-23_p-15_s-3\",\n        \"han-fei-zi_ch-23_p-15_s-4\",\n        \"han-fei-zi_ch-23_p-15_s-5\",\n        \"han-fei-zi_ch-23_p-15_s-6\",\n        \"han-fei-zi_ch-23_p-15_s-7\",\n        \"han-fei-zi_ch-23_p-15_s-8\",\n        \"han-fei-zi_ch-23_p-15_s-9\",\n        \"han-fei-zi_ch-23_p-15_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"王壽負書而且行，見徐馮於周塗，馮說道：事的人或事，為啊。為生於時，知的人或事無常事。書的人或事，言啊。言生於知，知的人或事不藏書。今子何獨負的而且行？於是王壽因焚他的書而且舞的。所以知的人或事不以言談教，而且慧的人或事不以藏書篋。此世的所過啊，而且王壽復的，是學不學啊。因此韓絕不是子評論說道：學不學，復歸眾人的所過啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「王壽負書而行，見徐馮於周塗，馮曰：「事者，為也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「王」、「壽」、「負」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「王壽負書而行見徐馮於周塗馮曰事者為也為生於時知者」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「為生於時，知者無常事」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 16,\n      \"canonicalText\": \"夫物有常容，因乘以導之，因隨物之容。故靜則建乎德，動則順乎道。宋人有為其君以象為楮葉者，三年而成。豐殺莖柯，毫芒繁澤，亂之楮葉之中而不可別也。此人遂以功食祿於宋邦。列子聞之曰：「使天地三年而成一葉，則物之有葉者寡矣。」故不乘天地之資，而載一人之身；不隨道理之數，而學一人之智；此皆一葉之行也。故冬耕之稼，后稷不能羨也；豐年大禾，臧獲不能惡也。以一人力，則后稷不足；隨自然，則臧獲有餘。故曰：「恃萬物之自然而不敢為也。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-16_s-1\",\n        \"han-fei-zi_ch-23_p-16_s-2\",\n        \"han-fei-zi_ch-23_p-16_s-3\",\n        \"han-fei-zi_ch-23_p-16_s-4\",\n        \"han-fei-zi_ch-23_p-16_s-5\",\n        \"han-fei-zi_ch-23_p-16_s-6\",\n        \"han-fei-zi_ch-23_p-16_s-7\",\n        \"han-fei-zi_ch-23_p-16_s-8\",\n        \"han-fei-zi_ch-23_p-16_s-9\",\n        \"han-fei-zi_ch-23_p-16_s-10\",\n        \"han-fei-zi_ch-23_p-16_s-11\",\n        \"han-fei-zi_ch-23_p-16_s-12\",\n        \"han-fei-zi_ch-23_p-16_s-13\",\n        \"han-fei-zi_ch-23_p-16_s-14\",\n        \"han-fei-zi_ch-23_p-16_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫物有常容，因乘以導的，因隨物的容。所以靜則建乎德，動則順乎道。宋人有為他的國君以象為楮葉的人或事，三年而且成。豐殺莖柯，毫芒繁澤，亂的楮葉的中而且不可別啊。此人遂以功食祿於宋邦。列子聞的說道：使天地三年而且成一葉，則物的有葉的人或事寡矣。所以不乘天地的資，而且載一人的身；不隨道理的數，而且學一人的智；此皆一葉的行啊。所以冬耕的稼，后稷不能羨啊；豐年大禾，臧獲不能惡啊。以一人力，則后稷不足；隨自然，則臧獲有餘。因此韓絕不是子評論說道：恃萬物的自然而且不敢為啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「夫物有常容，因乘以導之，因隨物之容」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「物」、「有」、「常」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫物有常容因乘以導之因隨物之容故靜則建乎德動則順」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「故靜則建乎德，動則順乎道」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 17,\n      \"canonicalText\": \"空竅者，神明之戶牖也。耳目竭於聲色，精神竭於外貌，故中無主。中無主則禍福雖如丘山無從識之，故曰：「不出於戶，可以知天下；不闚於牖，可以知天道。」此言神明之不離其實也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-17_s-1\",\n        \"han-fei-zi_ch-23_p-17_s-2\",\n        \"han-fei-zi_ch-23_p-17_s-3\",\n        \"han-fei-zi_ch-23_p-17_s-4\",\n        \"han-fei-zi_ch-23_p-17_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"空竅的人或事，神明的戶牖啊。耳目竭於聲色，精神竭於外貌，所以中無主。中無主則禍福雖如丘山無從識的，因此韓絕不是子評論說道：不出於戶，可以知天下；不闚於牖，可以知天道。此言神明的不離他的實啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「空竅者，神明之戶牖也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「空」、「竅」、「神」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「空竅者神明之戶牖也耳目竭於聲色精神竭於外貌故中無」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「耳目竭於聲色，精神竭於外貌，故中無主」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 18,\n      \"canonicalText\": \"趙襄主學御於王子期，俄而與於期逐，三易馬而三後。襄主曰：「子之教我御術未盡也。」對曰：「術已盡，用之則過也。凡御之所貴，馬體安於車，人心調於馬，而後可以進速致遠。今君後則欲逮臣，先則恐逮於臣。夫誘道爭遠，非先則後也。而先後心皆在於臣，上何以調於馬，此君之所以後也。」白公勝慮亂，罷朝，倒杖而策銳貫顊，血流至於地而不知。鄭人聞之曰：「顊之忘，將何為忘哉！」故曰：「其出彌遠者，其智彌少。」此言智周乎遠，則所遺在近也，是以聖人無常行也。能並智，故曰：「不行而知。」能並視，故曰：「不見而明。」隨時以舉事，因資而立功，用萬物之能而獲利其上，故曰：「不為而成。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-18_s-1\",\n        \"han-fei-zi_ch-23_p-18_s-2\",\n        \"han-fei-zi_ch-23_p-18_s-3\",\n        \"han-fei-zi_ch-23_p-18_s-4\",\n        \"han-fei-zi_ch-23_p-18_s-5\",\n        \"han-fei-zi_ch-23_p-18_s-6\",\n        \"han-fei-zi_ch-23_p-18_s-7\",\n        \"han-fei-zi_ch-23_p-18_s-8\",\n        \"han-fei-zi_ch-23_p-18_s-9\",\n        \"han-fei-zi_ch-23_p-18_s-10\",\n        \"han-fei-zi_ch-23_p-18_s-11\",\n        \"han-fei-zi_ch-23_p-18_s-12\",\n        \"han-fei-zi_ch-23_p-18_s-13\",\n        \"han-fei-zi_ch-23_p-18_s-14\",\n        \"han-fei-zi_ch-23_p-18_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"趙襄主學御於王子期，俄而且與於期逐，三易馬而且三後。襄主說道：子的教我御督察權術未盡啊。對說道：督察權術已盡，用的則過啊。凡御的所貴，馬體安於車，人心調於馬，而且後可以進速致遠。今國君後則欲逮臣屬，先則恐逮於臣屬。夫誘道爭遠，絕不是先則後啊。而且先後心皆在於臣屬，上何以調於馬，此國君的所以後啊。白公勝慮亂，罷朝，倒杖而且策銳貫顊，血流至於地而且不知。鄭人聞的說道：顊的忘，將何為忘哉！因此韓絕不是子評論說道：他的出彌遠的人或事，他的智彌少。此言智周乎遠，則所遺在近啊，是以聖人無常行啊。能並智，因此韓絕不是子評論說道：不行而且知。能並視，因此韓絕不是子評論說道：不見而且明。隨時以舉事，因資而且立功，用萬物的能而且獲利他的上，因此韓絕不是子評論說道：不為而且成。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「趙襄主學御於王子期，俄而與於期逐，三易馬而三後」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「趙」、「襄」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「趙襄主學御於王子期俄而與於期逐三易馬而三後襄主曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「襄主曰：「子之教我御術未盡也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 19,\n      \"canonicalText\": \"楚莊王蒞政三年，無令發，無政為也。右司馬御座而與王隱曰：「有鳥止南方之阜，三年不翅不飛不鳴，嘿然無聲，此為何名？」王曰：「三年不翅，將以長羽翼。不飛不鳴，將以觀民則。雖無飛，飛必沖天；雖無鳴，鳴必驚人。子釋之，不穀知之矣。」處半年，乃自聽政，所廢者十，所起者九，誅大臣五，舉處士六，而邦大治。舉兵誅齊，敗之徐州，勝晉於河雍，合諸侯於宋，遂霸天下。莊王不為小害善，故有大名；不蚤見示，故有大功。故曰：「大器晚成，大音希聲。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-19_s-1\",\n        \"han-fei-zi_ch-23_p-19_s-2\",\n        \"han-fei-zi_ch-23_p-19_s-3\",\n        \"han-fei-zi_ch-23_p-19_s-4\",\n        \"han-fei-zi_ch-23_p-19_s-5\",\n        \"han-fei-zi_ch-23_p-19_s-6\",\n        \"han-fei-zi_ch-23_p-19_s-7\",\n        \"han-fei-zi_ch-23_p-19_s-8\",\n        \"han-fei-zi_ch-23_p-19_s-9\",\n        \"han-fei-zi_ch-23_p-19_s-10\",\n        \"han-fei-zi_ch-23_p-19_s-11\",\n        \"han-fei-zi_ch-23_p-19_s-12\",\n        \"han-fei-zi_ch-23_p-19_s-13\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"楚莊王蒞政三年，無令發，無政為啊。右司馬御座而且與王隱說道：有鳥止南方的阜，三年不翅不飛不鳴，嘿然無聲，此為何名？王說道：三年不翅，將以長羽翼。不飛不鳴，將以觀民則。雖無飛，飛必沖天；雖無鳴，鳴必驚人。子釋的，不穀知的矣。處半年，乃自聽政，所廢的人或事十，所起的人或事九，誅大臣屬五，舉處士六，而且邦大治。舉兵誅齊，敗的徐州，勝晉於河雍，合諸侯於宋，遂霸天下。莊王不為小害善，所以有大名；不蚤見示，所以有大功。因此韓絕不是子評論說道：大器晚成，大音希聲。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「楚莊王蒞政三年，無令發，無政為也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「楚」、「莊」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「楚莊王蒞政三年無令發無政為也右司馬御座而與王隱曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「右司馬御座而與王隱曰：「有鳥止南方之阜，三年不翅不飛不鳴，嘿然無聲，此為何名」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 20,\n      \"canonicalText\": \"楚莊王欲伐越，杜子諫曰：「王之伐越何也？」曰：「政亂兵弱。」杜子曰：「臣愚患之。智如目也，能見百步之外而不能自見其睫。王之兵自敗於秦、晉，喪地數百里，此兵之弱也。莊蹻為盜於境內而吏不能禁，此政之亂也。王之弱亂非越之下也，而欲伐越，此智之如目也。」王乃止。故知之難，不在見人，在自見。故曰：「自見之謂明。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-20_s-1\",\n        \"han-fei-zi_ch-23_p-20_s-2\",\n        \"han-fei-zi_ch-23_p-20_s-3\",\n        \"han-fei-zi_ch-23_p-20_s-4\",\n        \"han-fei-zi_ch-23_p-20_s-5\",\n        \"han-fei-zi_ch-23_p-20_s-6\",\n        \"han-fei-zi_ch-23_p-20_s-7\",\n        \"han-fei-zi_ch-23_p-20_s-8\",\n        \"han-fei-zi_ch-23_p-20_s-9\",\n        \"han-fei-zi_ch-23_p-20_s-10\",\n        \"han-fei-zi_ch-23_p-20_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"楚莊王欲伐越，杜子諫說道：王的伐越何啊？說道：政亂兵弱。杜子說道：臣屬愚患的。智如目啊，能見百步的外而且不能自見他的睫。王的兵自敗於秦、晉，喪地數百里，此兵的弱啊。莊蹻為盜於境內而且吏不能禁，此政的亂啊。王的弱亂絕不是越的下啊，而且欲伐越，此智的如目啊。王乃止。所以知的難，不在見人，在自見。因此韓絕不是子評論說道：自見的謂明。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「楚莊王欲伐越，杜子諫曰：「王之伐越何也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「楚」、「莊」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「楚莊王欲伐越杜子諫曰王之伐越何也曰政亂兵弱杜子曰」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」曰：「政亂兵弱」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 21,\n      \"canonicalText\": \"子夏見曾子，曾子曰：「何肥也？」對曰：「戰勝故肥也。」曾子曰：「何謂也？」子夏曰：「吾入見先王之義則榮之，出見富貴之樂又榮之，兩者戰於胸中，未知勝負，故臞。今先王之義勝，故肥。」是以志之難也，不在勝人，在自勝也。故曰：「自勝之謂強。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-21_s-1\",\n        \"han-fei-zi_ch-23_p-21_s-2\",\n        \"han-fei-zi_ch-23_p-21_s-3\",\n        \"han-fei-zi_ch-23_p-21_s-4\",\n        \"han-fei-zi_ch-23_p-21_s-5\",\n        \"han-fei-zi_ch-23_p-21_s-6\",\n        \"han-fei-zi_ch-23_p-21_s-7\",\n        \"han-fei-zi_ch-23_p-21_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"子夏見曾子，曾子說道：何肥啊？對說道：戰勝所以肥啊。曾子說道：何謂啊？子夏說道：吾入見先王的義則榮的，出見富貴的樂又榮的，兩的人或事戰於胸中，未知勝負，所以臞。今先王的義勝，所以肥。是以志的難啊，不在勝人，在自勝啊。因此韓絕不是子評論說道：自勝的謂強。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「子夏見曾子，曾子曰：「何肥也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「子」、「夏」、「見」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「子夏見曾子曾子曰何肥也對曰戰勝故肥也曾子曰何謂也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「」對曰：「戰勝故肥也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"order\": 22,\n      \"canonicalText\": \"周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之。是膠鬲賢而費仲無道也。周惡賢者之得志也，故予費仲。文王舉太公於渭濱者，貴之也；而資費仲玉版者，是愛之也。故曰：「不貴其師，不愛其資，雖知大迷，是謂要妙。」\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-23_p-22_s-1\",\n        \"han-fei-zi_ch-23_p-22_s-2\",\n        \"han-fei-zi_ch-23_p-22_s-3\",\n        \"han-fei-zi_ch-23_p-22_s-4\",\n        \"han-fei-zi_ch-23_p-22_s-5\",\n        \"han-fei-zi_ch-23_p-22_s-6\",\n        \"han-fei-zi_ch-23_p-22_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"周有玉版，紂令膠鬲索的，文王不予，費仲來求，因予的。是膠鬲賢而且費仲無道啊。周惡賢的人或事的得志啊，所以予費仲。文王舉太公於渭濱的人或事，貴的啊；而且資費仲玉版的人或事，是愛的啊。因此韓絕不是子評論說道：不貴他的師，不愛他的資，雖知大迷，是謂要妙。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈喻老〉。韓非深刻融合法、術、勢三大治國精要，此處「周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「周」、「有」、「玉」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「周有玉版紂令膠鬲索之文王不予費仲來求因予之是膠鬲」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「是膠鬲賢而費仲無道也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-23_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"天下有道無急患則曰靜，遽傳不用，故曰：「卻走馬以糞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"」天下無道，攻擊不休，相守數年不已，甲冑生蟣蝨，鷰雀處帷幄，而兵不歸，故曰：「戎馬生於郊。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"翟人有獻豐狐、玄豹之皮於晉文公，文公受客皮而歎曰：「此以皮之美自為罪。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"」夫治國者以名號為罪，徐偃王是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"以城與地為罪，虞、虢是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：「罪莫大於可欲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"智伯兼範、中行而攻趙不已，韓、魏反之，軍敗晉陽，身死高梁之東，遂卒被分，漆其首以為溲器，故曰：「禍莫大於不知足。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"虞君欲屈產之乘，與垂棘之璧，不聽宮之奇，故邦亡身死，故曰：「咎莫憯於欲得。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"邦以存為常，霸王其可也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"身以生為常，富貴其可也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"不欲自害則邦不亡身不死，故曰：「知足之為足矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"楚莊王既勝狩於河雍，歸而賞孫叔敖，孫叔敖請漢間之地，沙石之處。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"楚邦之法，祿臣再世而收地，唯孫叔敖獨在。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"此不以其邦為收者，瘠也，故九世而祀不絕。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：「善建不拔，善抱不脫，子孫以其祭祀世世不輟」，孫叔敖之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"制在己曰重，不離位曰靜。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"重則能使輕，靜則能使躁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"故曰：「重為輕根，靜為躁君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰君子終日行不離輜重也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"」邦者，人君之輜重也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"主父生傳其邦，此離其輜重者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"故雖有代、雲中之樂，超然已無趙矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"主父，萬乘之主，而以身輕於天下，無勢之謂輕，離位之謂躁，是以生幽而死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-7_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"故曰：「輕則失臣，躁則失君」，主父之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"勢重者，人君之淵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"君人者勢重於人臣之閒，失則不可復得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"簡公失之於田成，晉公失之於六卿，而邦亡身死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：「魚不可脫於深淵。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"」賞罰者，邦之利器也，在君則制臣，在臣則勝君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"君見賞，臣則損之以為德；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"君見罰，臣則益之以為威。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"人君見賞而人臣用其勢，人君見罰而人臣乘其威。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"故曰：「邦之利器不可以示人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"越王入宦於吳，而觀之伐齊以弊吳。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"吳兵既勝齊人於艾陵，張之於江、濟，強之於黃池，故可制於五湖。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"故曰：「將欲翕之，必固張之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"將欲弱之，必固強之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"」晉獻公將欲襲虞，遺之以璧馬；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"知伯將襲仇由，遺之以廣車。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"故曰：「將欲取之，必固與之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"」起事於無形，而要大功於天下，是謂微明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-9_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"處小弱而重自卑謂損弱勝強也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"有形之類，大必起於小；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"行久之物，族必起於少。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"故曰：「天下之難事必作於易，天下之大事必作於細。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"」是以欲制物者於其細也，故曰：「圖難於其易也，為大於其細也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"」千丈之隄以螻蟻之穴潰，百尺之室以突隙之煙焚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"故曰：白圭之行隄也塞其穴，丈人之慎火也塗其隙。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"是以白圭無水難，丈人無火患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"此皆慎易以避難，敬細以遠大者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"扁鵲見蔡桓公，立有間，扁鵲曰：「君有疾在腠理，不治將恐深。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"」桓侯曰：「寡人無。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"」扁鵲出，桓侯曰：「醫之好治不病以為功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"」居十日，扁鵲復見曰：「君之病在肌膚，不治將益深。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 13,\n      \"canonicalText\": \"」桓侯不應。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 14,\n      \"canonicalText\": \"扁鵲出，桓侯又不悅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 15,\n      \"canonicalText\": \"居十日，扁鵲復見曰：「君之病在腸胃，不治將益深。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 16,\n      \"canonicalText\": \"」桓侯又不應。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 17,\n      \"canonicalText\": \"扁鵲出，桓侯又不悅。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 18,\n      \"canonicalText\": \"居十日，扁鵲望桓侯而還走。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 19,\n      \"canonicalText\": \"桓侯故使人問之，扁鵲曰：「疾在腠理，湯熨之所及也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 20,\n      \"canonicalText\": \"在肌膚，鍼石之所及也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 21,\n      \"canonicalText\": \"在腸胃，火齊之所及也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 22,\n      \"canonicalText\": \"在骨髓，司命之所屬，無奈何也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 23,\n      \"canonicalText\": \"今在骨髓，臣是以無請也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 24,\n      \"canonicalText\": \"」居五日，桓公體痛，使人索扁鵲，已逃秦矣，桓侯遂死。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 25,\n      \"canonicalText\": \"故良醫之治病也，攻之於腠理，此皆爭之於小者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-10_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-10\",\n      \"order\": 26,\n      \"canonicalText\": \"夫事之禍福亦有腠理之地，故曰：聖人蚤從事焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"昔晉公子重耳出亡過鄭，鄭君不禮，叔瞻諫曰：「此賢公子也，君厚待之，可以積德。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"」鄭君不聽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"叔瞻又諫曰：「不厚待之，不若殺之，無令有後患。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"」鄭君又不聽。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"及公子返晉邦，舉兵伐鄭，大破之，取八城焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"晉獻公以垂棘之璧假道於虞而伐虢，大夫宮之奇諫曰：「不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"脣亡而齒寒，虞、虢相救，非相德也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"今日晉滅虢，明日虞必隨之亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"」虞君不聽，受其璧而假之道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"晉已取虢，還，反滅虞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"此二臣者皆爭於腠理者也，而二君不用也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"然則叔瞻、宮之奇亦虞、鄭之扁鵲也，而二君不聽，故鄭以破，虞以亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"故曰：「其安易持也，其未兆易謀也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-11_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-11\",\n      \"order\": 14,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"昔者紂為象箸而箕子怖。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"以為象箸必不加於土鉶，必將犀玉之杯。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"象箸玉杯必不羹菽藿，則必旄象豹胎。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"旄象豹胎必不衣短褐而食於茅屋之下，則錦衣九重，廣室高臺。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"吾畏其卒，故怖其始。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"居五年，紂為肉圃，設炮烙，登糟邱，臨酒池，紂遂以亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"故箕子見象箸以知天下之禍，故曰：「見小曰明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"句踐入宦於吳，身執干戈為吳王洗馬，故能殺夫差於姑蘇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"文王見詈於王門，顏色不變，而武王擒紂於牧野。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"故曰：「守柔曰強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"」越王之霸也不病宦，武王之王也不病詈。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"故曰：「聖人之不病也，以其不病，是以無病也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-13_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"宋之鄙人得璞玉而獻之子罕，子罕不受，鄙人曰：「此寶也，宜為君子器，不宜為細人用。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"」子罕曰：「爾以玉為寶，我以不受子玉為寶。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"」是鄙人慾玉，而子罕不欲玉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：「欲不欲，而不貴難得之貨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-14_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"王壽負書而行，見徐馮於周塗，馮曰：「事者，為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"為生於時，知者無常事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"書者，言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"言生於知，知者不藏書。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"今子何獨負之而行？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"」於是王壽因焚其書而舞之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 7,\n      \"canonicalText\": \"故知者不以言談教，而慧者不以藏書篋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 8,\n      \"canonicalText\": \"此世之所過也，而王壽復之，是學不學也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 9,\n      \"canonicalText\": \"故曰：「學不學，復歸眾人之所過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-15_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-15\",\n      \"order\": 10,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"夫物有常容，因乘以導之，因隨物之容。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"故靜則建乎德，動則順乎道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"宋人有為其君以象為楮葉者，三年而成。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"豐殺莖柯，毫芒繁澤，亂之楮葉之中而不可別也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 5,\n      \"canonicalText\": \"此人遂以功食祿於宋邦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 6,\n      \"canonicalText\": \"列子聞之曰：「使天地三年而成一葉，則物之有葉者寡矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 7,\n      \"canonicalText\": \"」故不乘天地之資，而載一人之身；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 8,\n      \"canonicalText\": \"不隨道理之數，而學一人之智；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 9,\n      \"canonicalText\": \"此皆一葉之行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 10,\n      \"canonicalText\": \"故冬耕之稼，后稷不能羨也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 11,\n      \"canonicalText\": \"豐年大禾，臧獲不能惡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 12,\n      \"canonicalText\": \"以一人力，則后稷不足；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 13,\n      \"canonicalText\": \"隨自然，則臧獲有餘。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 14,\n      \"canonicalText\": \"故曰：「恃萬物之自然而不敢為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-16_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-16\",\n      \"order\": 15,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"空竅者，神明之戶牖也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"耳目竭於聲色，精神竭於外貌，故中無主。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"中無主則禍福雖如丘山無從識之，故曰：「不出於戶，可以知天下；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"不闚於牖，可以知天道。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-17_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"」此言神明之不離其實也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"趙襄主學御於王子期，俄而與於期逐，三易馬而三後。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"襄主曰：「子之教我御術未盡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"」對曰：「術已盡，用之則過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"凡御之所貴，馬體安於車，人心調於馬，而後可以進速致遠。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"今君後則欲逮臣，先則恐逮於臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"夫誘道爭遠，非先則後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"而先後心皆在於臣，上何以調於馬，此君之所以後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"」白公勝慮亂，罷朝，倒杖而策銳貫顊，血流至於地而不知。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"鄭人聞之曰：「顊之忘，將何為忘哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"」故曰：「其出彌遠者，其智彌少。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 11,\n      \"canonicalText\": \"」此言智周乎遠，則所遺在近也，是以聖人無常行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 12,\n      \"canonicalText\": \"能並智，故曰：「不行而知。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 13,\n      \"canonicalText\": \"」能並視，故曰：「不見而明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 14,\n      \"canonicalText\": \"」隨時以舉事，因資而立功，用萬物之能而獲利其上，故曰：「不為而成。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-18_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-18\",\n      \"order\": 15,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"楚莊王蒞政三年，無令發，無政為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"右司馬御座而與王隱曰：「有鳥止南方之阜，三年不翅不飛不鳴，嘿然無聲，此為何名？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"」王曰：「三年不翅，將以長羽翼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"不飛不鳴，將以觀民則。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"雖無飛，飛必沖天；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"雖無鳴，鳴必驚人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 7,\n      \"canonicalText\": \"子釋之，不穀知之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 8,\n      \"canonicalText\": \"」處半年，乃自聽政，所廢者十，所起者九，誅大臣五，舉處士六，而邦大治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 9,\n      \"canonicalText\": \"舉兵誅齊，敗之徐州，勝晉於河雍，合諸侯於宋，遂霸天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 10,\n      \"canonicalText\": \"莊王不為小害善，故有大名；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 11,\n      \"canonicalText\": \"不蚤見示，故有大功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 12,\n      \"canonicalText\": \"故曰：「大器晚成，大音希聲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-19_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-19\",\n      \"order\": 13,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"楚莊王欲伐越，杜子諫曰：「王之伐越何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"」曰：「政亂兵弱。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"」杜子曰：「臣愚患之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"智如目也，能見百步之外而不能自見其睫。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 5,\n      \"canonicalText\": \"王之兵自敗於秦、晉，喪地數百里，此兵之弱也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 6,\n      \"canonicalText\": \"莊蹻為盜於境內而吏不能禁，此政之亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 7,\n      \"canonicalText\": \"王之弱亂非越之下也，而欲伐越，此智之如目也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 8,\n      \"canonicalText\": \"」王乃止。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 9,\n      \"canonicalText\": \"故知之難，不在見人，在自見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 10,\n      \"canonicalText\": \"故曰：「自見之謂明。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-20_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-20\",\n      \"order\": 11,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 1,\n      \"canonicalText\": \"子夏見曾子，曾子曰：「何肥也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 2,\n      \"canonicalText\": \"」對曰：「戰勝故肥也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 3,\n      \"canonicalText\": \"」曾子曰：「何謂也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 4,\n      \"canonicalText\": \"」子夏曰：「吾入見先王之義則榮之，出見富貴之樂又榮之，兩者戰於胸中，未知勝負，故臞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 5,\n      \"canonicalText\": \"今先王之義勝，故肥。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 6,\n      \"canonicalText\": \"」是以志之難也，不在勝人，在自勝也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 7,\n      \"canonicalText\": \"故曰：「自勝之謂強。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-21_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-21\",\n      \"order\": 8,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 1,\n      \"canonicalText\": \"周有玉版，紂令膠鬲索之，文王不予，費仲來求，因予之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 2,\n      \"canonicalText\": \"是膠鬲賢而費仲無道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 3,\n      \"canonicalText\": \"周惡賢者之得志也，故予費仲。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 4,\n      \"canonicalText\": \"文王舉太公於渭濱者，貴之也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 5,\n      \"canonicalText\": \"而資費仲玉版者，是愛之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 6,\n      \"canonicalText\": \"故曰：「不貴其師，不愛其資，雖知大迷，是謂要妙。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-23_p-22_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-23\",\n      \"passageId\": \"han-fei-zi_ch-23_p-22\",\n      \"order\": 7,\n      \"canonicalText\": \"」\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
